const end = Date.now() + 60000;
let lastXp = sdk.getSkillXp('Mining');
while (Date.now() < end) {
  const state = sdk.getState();
  if (!state) break;
  // drop ores/gems
  for (const it of state.inventory) {
    if (/ore$|^uncut /i.test(it.name)) await sdk.sendDropItem(it.slot);
  }
  const skill = state.skills.find(s => s.name === 'Mining');
  const lvl = skill ? skill.level : 1;
  const pat = lvl >= 10 ? /rocks (iron|tin|copper) ore/i : /rocks (tin|copper) ore/i;
  const rocks = state.nearbyLocs.filter(l => pat.test(l.name)).sort((a,b) => a.distance - b.distance);
  if (rocks.length) {
    const rock = rocks[0];
    if (rock.distance > 2) { await sdk.sendWalk(rock.x, rock.z, true); await sdk.waitForTicks(2); }
    const mineOpt = rock.optionsWithIndex.find(o => /^mine$/i.test(o.text));
    if (mineOpt) await sdk.sendInteractLoc(rock.x, rock.z, rock.id, mineOpt.opIndex);
  }
  await sdk.waitForTicks(3);
}
const s = sdk.getState().skills.find(x => x.name === 'Mining');
return { level: s.level, xp: s.experience ?? s.xp, gained: sdk.getSkillXp('Mining') - lastXp };

const end = Date.now() + 5*60*1000;
let clicks = 0, drops = 0;
while (Date.now() < end) {
  const state = sdk.getState();
  if (!state) { await sdk.waitForTicks(2); continue; }
  if (state.dialog && state.dialog.isOpen) { await sdk.sendClickDialog(0); await sdk.waitForTicks(1); continue; }
  const ores = state.inventory.filter(i => /ore$|^uncut /i.test(i.name));
  const mining = state.player.animId === 625;
  if (ores.length >= 14 && !mining) {
    for (const o of ores) { await sdk.sendDropItem(o.slot); drops++; }
    continue;
  }
  if (mining) { await sdk.waitForTicks(2); continue; }
  let rock = state.nearbyLocs.filter(l => /rocks iron ore/i.test(l.name)).sort((a,b)=>a.distance-b.distance)[0];
  if (!rock) rock = state.nearbyLocs.filter(l => /rocks .*ore/i.test(l.name)).sort((a,b)=>a.distance-b.distance)[0];
  if (rock) {
    if (rock.distance > 2) { await sdk.sendWalk(rock.x, rock.z, true); await sdk.waitForTicks(2); continue; }
    const opt = rock.optionsWithIndex.find(o => /^mine$/i.test(o.text));
    if (opt) { await sdk.sendInteractLoc(rock.x, rock.z, rock.id, opt.opIndex); clicks++; }
  }
  await sdk.waitForTicks(2);
}
return { clicks, drops, xp: sdk.getSkillXp('Mining') };

